import React, { useEffect, useState } from "react";
import axios from "axios";
import "./ReferralHistoryTable.css"; // optional CSS file for styling

// .env থেকে base URL নাও
const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || "http://localhost:8080/api";

export default function ReferralHistoryTable() {
  const [referrals, setReferrals] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchReferralHistory();
  }, []);

  const fetchReferralHistory = async () => {
    try {
      const token = localStorage.getItem("authToken"); // JWT টোকেন
      const res = await axios.get(`${API_BASE_URL}/bonus-history/my-referrals`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      const referralData = res.data.filter(item => item.type === "Referral");
      referralData.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt)); // latest first
      setReferrals(referralData);
    } catch (err) {
      console.error("Error fetching referral history:", err);
    } finally {
      setLoading(false);
    }
  };

  if (loading) return <p>Loading referral history...</p>;
  if (referrals.length === 0) return <p>No referral bonuses yet.</p>;

  return (
    <div className="referral-table-container">
      <h2>Referral Bonus History</h2>
      <table className="referral-table">
        <thead>
          <tr>
            <th>#</th>
            <th>Game ID / Referrer</th>
            <th>Bonus Amount</th>
            <th>Date</th>
          </tr>
        </thead>
        <tbody>
          {referrals.map((item, index) => (
            <tr key={index}>
              <td>{index + 1}</td>
              <td>{item.sourceGameId || "N/A"}</td>
              <td style={{ color: "#0a9d58", fontWeight: "600" }}>
                {item.amount}
              </td>
              <td>{new Date(item.createdAt).toLocaleString()}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
